screens=[]
BASE={
 'Shared access':('Adult/public; never an incident-time child login gate.','Readable errors, screen-reader labels, autofill and scalable text. Preserve safe return destination.'),
 'Parent / caregiver':('Guardian owns household; invited caregiver gets explicit child/action grants. Invitation/authority verification is planned, not implied by emergency-contact status.','Large touch targets, logical focus, text scaling and non-color status cues. Do not expose another household via links/back stack.'),
 'Linked child':('Scoped linked-child credential only. No billing, household administration, staff instructions or incident-time parent approval.','Adapt to individual communication/motor/sensory needs; non-reader symbols with text/assistive labels; no color/audio-only cues or mandatory confirmation barrier.'),
 'Staff access':('Approved organization staff identity and role; consumer sessions do not grant staff access.','Keyboard and screen-reader support; errors preserve safe form state. Staff MFA/identity process is planned.'),
 'Coordinator':('Authorized incident region; current owner for progress/closure, audited takeover where permitted.','Keyboard-accessible operations, persistent incident identity, time/source labels and non-color urgency.'),
 'Responder':('Offered crew sees offer metadata only; accepted assigned crew gets necessary care/location. Access ends with assignment.','Field-readable controls, assistive labels, clear confirmation of recorded transitions; no unsafe distraction assumptions.'),
 'Accommodation':('Authorized placement staff/coordinator only; care/release authority must be verified separately. Staff API/verification is incomplete.','Readable handover forms, keyboard access, explicit identity/authority mismatches, no color-only approval.'),
 'Administration':('Audited privileged configuration role; no automatic blanket access to child data.','Keyboard-accessible forms, clear audit/review history, deliberate changes and no secret exposure.'),
}
def add(id,name,surface,route,purpose,actions,entry,exit,states,phase,refs,api):
 access,a11y=BASE[surface]
 screens.append(dict(id=id,name=name,surface=surface,route=route,purpose=purpose,actions=actions,entry=entry,exit=exit,states=states,permissions=access,accessibility=a11y,phase=phase,trace=refs,api=api))
